+import type { Kysely } from "kysely";
+import type { Database } from "./schema.js";
+
+/**
+ * Run `fn` in a transaction, or directly against `db` if it's already one.
+ * Lets service functions that pair a mutation with its audit write compose
+ * safely — e.g. `upsertSiteScopedAssignment` runs several such functions
+ * inside its own transaction; without this check each would open a nested
+ * transaction (a savepoint) instead of joining the outer one.
+ */
+export async function withTransaction<T>(
+	db: Kysely<Database>,
+	fn: (trx: Kysely<Database>) => Promise<T>,
+): Promise<T> {
+	if (db.isTransaction) {
+		return fn(db);
+	}
+	return db.transaction().execute(fn);
+}

